<template><section v-if="loading || error || hasNeeds" class="billing-needs" aria-label="Your billing needs"><h3>Your billing needs</h3><p v-if="loading" role="status">Checking your billing tasks…</p><p v-else-if="error" role="alert">{{ error }} <button @click="load">Try again</button></p><div v-else class="needs"><button v-if="needs.dueCents > 0" @click="$emit('navigate','billing')"><strong>{{ money(needs.dueCents) }}</strong><span>Your verified share · view and pay</span></button><button v-if="needs.pendingPayments" @click="$emit('navigate','billing')"><strong>Payment processing</strong><span>Review your pending payment</span></button><button v-if="needs.splitRequests" @click="$emit('navigate','billing')"><strong>{{ needs.splitRequests }} shared payment request{{ needs.splitRequests === 1 ? '' : 's' }}</strong><span>Review the percentage assigned to you</span></button><button v-if="needs.insuranceCards.length" @click="$emit('navigate','payment_methods')"><strong>{{ needs.insuranceCards.some(c=>c.state==='missing') ? 'Insurance card upload' : 'Insurance help requested' }}</strong><span>Front and back · secure upload</span></button><router-link v-for="task in needs.paymentTasks" :key="task.id" :to="{path:'/billing/complete',query:{task:task.id,agencyId}}"><strong>{{ task.title }}</strong><span>Complete your payment setup</span></router-link></div></section></template>
<script setup>
import {computed,ref,watch,onBeforeUnmount} from 'vue';
import api from '../../services/api';
const props=defineProps({agencyId:[Number,String],clientId:[Number,String]});defineEmits(['navigate']);
const needs=ref(null),loading=ref(false),error=ref('');let generation=0;
const hasNeeds=computed(()=>needs.value&&(needs.value.dueCents>0||needs.value.pendingPayments||needs.value.splitRequests||needs.value.insuranceCards.length||needs.value.paymentTasks.length));
const money=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:'USD'}).format(n/100);
async function load(){const current=++generation;needs.value=null;error.value='';if(!props.agencyId)return;loading.value=true;try{const {data}=await api.get('/family-billing/needs',{params:{agencyId:props.agencyId,...(props.clientId?{clientId:props.clientId}:{})}});if(current===generation)needs.value=data;}catch{if(current===generation)error.value='Billing tasks could not be checked.';}finally{if(current===generation)loading.value=false;}}
watch(()=>[props.agencyId,props.clientId],load,{immediate:true});onBeforeUnmount(()=>generation++);
</script>
<style scoped>
.billing-needs{background:var(--bg-card,#fff);border:1px solid var(--border,#dbe4ef);border-radius:14px;padding:20px;margin:16px 0}.billing-needs h3{margin:0 0 12px}.needs{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.needs button,.needs a{display:grid;gap:7px;text-align:left;font:inherit;text-decoration:none;background:var(--bg-card,#fff);color:#174c95;border:1px solid #c6d7ef;padding:16px;border-radius:10px;cursor:pointer}.needs span{font-size:.9rem;color:var(--text-secondary,#546980)}
</style>
